INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (94141,0,0,'Good choice, just don\'t call me \'champion\'. Ever.',12,0,100.0,274,0,69544,120203,0,'LegionCore');
