INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (95464,0,0,'Highlord Tirion Fordring\'s last light fades.',16,0,100.0,0,0,0,96198,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (96813,0,0,'I have just the beast for this special task.',12,0,100.0,0,0,0,102319,0,'LegionCore');
