INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (98092,0,0,'Be careful, boss. Outland\'s a pretty dangerous place, an\' Shattrath\'s not that much better.',12,0,100.0,6,0,0,120219,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (98092,1,0,'Watch your back, and your pockets.',12,0,100.0,1,0,0,120221,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (98092,2,0,'Just make sure to tell everyone to be real nice to him. Otherwise, we might all wake up dead tomorrow. Ya know what I mean?',12,0,100.0,5,0,0,120256,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (98099,0,0,'I consider myself an adept hunter of the undead, and even I didn\'t notice at first.',12,0,100.0,0,0,81245,127066,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (98099,1,0,'But look what happens when I slice right here...',12,0,100.0,0,0,81246,127067,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (98099,2,0,'You will not regret this choice, Shadowblade. I will take out any Legion demon or conspirator who crosses my path!',12,0,100.0,66,0,81239,127696,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (98099,3,0,'He spoke in coherent thoughts, and his skin... so well-preserved. But a few telltale signs gave him away.',12,0,100.0,1,0,81248,127069,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (98099,4,0,'It seems Legion dreadlords have found a way to craft undead operatives so lifelike that even I have difficulty detecting them!',12,0,100.0,0,0,81249,127070,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (98099,5,0,'The demons knew the Illidari would find them if they tried to infiltrate our cities again, so they sent in these... homunculi.',12,0,100.0,0,0,81250,127071,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (98099,6,0,'Our agents have identified suspected homunculi in Silvermoon and the Exodar.',12,0,100.0,1,0,81251,127072,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (98099,7,0,'We can\'t risk you carrying out an assassination in an ally\'s city, but no one will question you taking down a target in the Exodar. While you handle that mark, we\'ll see to the matter in Silvermoon.',12,0,100.0,274,0,81253,127083,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (98099,8,0,'Remember... even though you\'re trying to help them, the Alliance will assume you\'re attacking one of their own.',12,0,100.0,1,0,81255,127084,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (98099,9,0,'Remember... even though you\'re trying to help them, the Horde will assume you\'re attacking one of their own.',12,0,100.0,1,0,81254,127074,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (98099,10,0,'',12,0,100.0,274,0,81252,0,0,'LegionCore');
