INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (103761,3,0,'Now, sharpen your blades for the battles to come! The Illidari will prevail!',12,0,100.0,0,0,82844,129215,0,'LegionCore');
