INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (105333,1,0,'Akaari is in this very city as we speak, spying for her masters.',12,0,100.0,0,0,0,108105,0,'LegionCore');
